WITH unpacked AS (SELECT id, host, log_ts, status_code, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, context['trace'] AS trace, SIZE(context) AS num_context, COALESCE(context['trace'], 'unknown') AS trace_or_default, COALESCE(context['version'], 'direct') AS version_or_default FROM app_logs) SELECT *, FIRST_VALUE(version_or_default, TRUE) OVER (ORDER BY num_context, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_version_or_default, FIRST_VALUE(version_or_default, TRUE) OVER (PARTITION BY host ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_version_or_default_2 FROM unpacked;
